"""Frozen deck chrome (same look as 2026.09.11 / 09.18 / 09.25). deck.py fills the slides in between."""
HEAD = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>{TITLE} &middot; hu-po &middot; {DATE}</title>\n<style>\n  :root{\n    --bg:#0B0E0F; --panel:#141A1B; --ink:#E9EFED; --muted:#93A29E; --faint:#63736F;\n    --live:#56E0BE; --rule:#212A2A;\n    --sans:"Helvetica Neue",Helvetica,Arial,system-ui,sans-serif;\n    --mono:ui-monospace,"SF Mono","DejaVu Sans Mono",Menlo,Consolas,monospace;\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  html,body{height:100%;background:#000;color:var(--ink);font-family:var(--sans);overflow:hidden}\n\n  #stage{position:fixed;inset:0;background:#000;overflow:hidden}\n  #deck{width:1920px;height:1080px;position:absolute;left:0;top:0;transform-origin:0 0;background:var(--bg);overflow:hidden}\n  .slide{position:absolute;inset:0;display:none}\n  .slide.on{display:grid}\n\n  /* title */\n  .title{grid-template-rows:1fr;padding:0}\n  .title img{width:100%;height:100%;object-fit:contain;background:var(--bg);display:block}\n\n  /* section divider */\n  .sec{grid-template-rows:1fr;padding:100px 130px}\n  .secbody{display:flex;flex-direction:column;justify-content:center;gap:38px;max-width:1520px}\n  .sec .num{font-family:var(--mono);font-size:30px;letter-spacing:.2em;color:var(--live)}\n  .sec h2{font-size:94px;line-height:1.03;letter-spacing:-.03em;font-weight:700;text-wrap:balance}\n  .sec .blurb{font-size:36px;line-height:1.42;color:var(--muted);max-width:1340px;\n              padding-top:30px;border-top:1px solid var(--rule)}\n\n  /* figure */\n  .fig{grid-template-rows:1fr auto auto;padding:38px 56px 28px;gap:14px}\n  .fig .frame{min-height:0;background:#fff;border:1px solid var(--rule);padding:16px}\n  .fig img,.fig video{width:100%;height:100%;object-fit:contain;display:block}\n  .fig .frame.dark{background:#000}\n  .fig .ctx{font-size:25px;line-height:1.42;color:var(--ink);text-align:left;\n            max-width:1660px;justify-self:center;text-wrap:pretty}\n  .fig .ctx b{color:#fff;font-weight:600}\n  .fig .cite{font-family:var(--mono);font-size:21px;letter-spacing:.03em;color:var(--faint);text-align:center}\n\n  /* references */\n  .refs{grid-template-rows:1fr;padding:56px 80px}\n  .reflist{display:grid;grid-template-columns:repeat(3,1fr);gap:0 44px;align-content:center}\n  .ref{display:grid;grid-template-columns:118px 1fr;gap:14px;padding:10px 0;border-bottom:1px solid var(--rule)}\n  .ref code{font-family:var(--mono);font-size:17px;color:var(--live)}\n  .ref .t b{display:block;font-size:19px;font-weight:600;line-height:1.22}\n  .ref .t span{font-family:var(--mono);font-size:15px;color:var(--faint)}\n\n  /* overview */\n  #overview{position:fixed;inset:0;background:rgba(6,9,10,.97);z-index:20;display:none;overflow-y:auto;padding:26px}\n  body.ov #overview{display:block}\n  .ovgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:14px}\n  .ov{background:var(--panel);border:1px solid var(--rule);padding:0;cursor:pointer;\n      display:flex;flex-direction:column;gap:0;text-align:left;color:inherit;font:inherit;overflow:hidden}\n  .ov:hover,.ov:focus-visible{border-color:var(--live);outline:none}\n  .ov img{width:100%;aspect-ratio:16/10;object-fit:contain;background:#fff;display:block}\n  .ovcard{width:100%;aspect-ratio:16/10;background:linear-gradient(135deg,#182120,#0E1414);display:block}\n  .ov em{font-family:var(--mono);font-size:11px;font-style:normal;color:var(--muted);\n         padding:7px 8px;line-height:1.3;letter-spacing:.02em}\n  .ov.cur{border-color:var(--live)}\n  .ov.cur em{color:var(--live)}\n\n  /* hud */\n  #hud{position:fixed;left:0;right:0;bottom:0;display:flex;gap:16px;align-items:center;\n       padding:9px 16px;font-family:var(--mono);font-size:12px;letter-spacing:.09em;color:var(--faint);\n       background:linear-gradient(to top,rgba(0,0,0,.85),rgba(0,0,0,0));pointer-events:none;z-index:10}\n  #hud .grow{flex:1}\n  #prog{position:fixed;left:0;top:0;height:3px;background:var(--live);width:0;z-index:11}\n  body.clean #hud,body.clean #prog{opacity:0}\n  @media (prefers-reduced-motion:no-preference){#prog{transition:width .14s linear}}\n</style>\n</head>\n<body>\n<div id="prog"></div>\n<div id="stage"><div id="deck">'
TAIL_PRE = '</div></div>'
TAIL_POST = '</div><div id="hud">\n  <span id="counter">1 / 66</span>\n  <span id="where"></span>\n  <span class="grow"></span>\n  <span>&larr; &rarr; SLIDE &middot; [ ] SECTION &middot; O OVERVIEW &middot; F FULLSCREEN &middot; C CLEAN</span>\n</div>\n<script>\n(function(){\n  var slides=[].slice.call(document.querySelectorAll(\'.slide\'));\n  var deck=document.getElementById(\'deck\');\n  var counter=document.getElementById(\'counter\');\n  var where=document.getElementById(\'where\');\n  var prog=document.getElementById(\'prog\');\n  var ovs=[].slice.call(document.querySelectorAll(\'.ov\'));\n  var cards=[];\n  slides.forEach(function(s,k){ if(s.classList.contains(\'sec\')) cards.push(k); });\n  var i=0;\n\n  function label(k){\n    var b=ovs[k]?ovs[k].querySelector(\'em\'):null;\n    if(!b) return \'\';\n    return b.textContent.replace(/^\\d+\\.\\s*/,\'\');\n  }\n  function show(n){\n    i=Math.max(0,Math.min(slides.length-1,n));\n    slides.forEach(function(s,k){s.classList.toggle(\'on\',k===i);});\n    ovs.forEach(function(b,k){b.classList.toggle(\'cur\',k===i);});\n    counter.textContent=(i+1)+\' / \'+slides.length;\n    where.textContent=label(i);\n    prog.style.width=(i/(slides.length-1)*100)+\'%\';\n    try{history.replaceState(null,\'\',\'#\'+(i+1));}catch(e){}\n  }\n  function fit(){\n    var s=Math.min(innerWidth/1920,innerHeight/1080);\n    deck.style.transform=\'translate(\'+((innerWidth-1920*s)/2)+\'px,\'+((innerHeight-1080*s)/2)+\'px) scale(\'+s+\')\';\n  }\n  addEventListener(\'resize\',fit); fit();\n\n  function fromHash(){var n=parseInt((location.hash||\'\').replace(\'#\',\'\'),10);return isNaN(n)?0:n-1;}\n  show(fromHash());\n  addEventListener(\'hashchange\',function(){if(fromHash()!==i)show(fromHash());});\n\n  function paper(dir){\n    var t=null;\n    for(var k=0;k<cards.length;k++){\n      if(dir>0&&cards[k]>i){t=cards[k];break;}\n      if(dir<0&&cards[k]<i)t=cards[k];\n    }\n    if(t!==null)show(t);\n  }\n\n  document.addEventListener(\'keydown\',function(e){\n    var k=e.key;\n    if(document.body.classList.contains(\'ov\')&&(k===\'Escape\'||k===\'o\'||k===\'O\')){\n      document.body.classList.remove(\'ov\');e.preventDefault();return;}\n    if(k===\'ArrowRight\'||k===\' \'||k===\'PageDown\'||k===\'j\'){show(i+1);e.preventDefault();}\n    else if(k===\'ArrowLeft\'||k===\'PageUp\'||k===\'k\'){show(i-1);e.preventDefault();}\n    else if(k===\']\'){paper(1);e.preventDefault();}\n    else if(k===\'[\'){paper(-1);e.preventDefault();}\n    else if(k===\'Home\'){show(0);}\n    else if(k===\'End\'){show(slides.length-1);}\n    else if(k===\'o\'||k===\'O\'){document.body.classList.add(\'ov\');\n      var c=ovs[i];if(c)c.scrollIntoView({block:\'center\'});e.preventDefault();}\n    else if(k===\'c\'||k===\'C\'){document.body.classList.toggle(\'clean\');}\n    else if(k===\'f\'||k===\'F\'){\n      if(document.fullscreenElement)document.exitFullscreen();\n      else if(document.documentElement.requestFullscreen)document.documentElement.requestFullscreen();}\n  });\n\n  ovs.forEach(function(b){b.addEventListener(\'click\',function(){\n    show(parseInt(b.dataset.i,10));document.body.classList.remove(\'ov\');});});\n\n  document.getElementById(\'stage\').addEventListener(\'click\',function(e){\n    show(e.clientX<innerWidth*0.28?i-1:i+1);});\n})();\n</script>\n</body>\n</html>\n'
